77	export type CheckoutResult =
78	  | {
79	      success: true;
80	      invoiceNumber: string;
81	      transactionId: string;
82	      printJobs: KitchenPrintJobPayload[];
83	      receiptPrintJobs: KitchenPrintJobPayload[];
84	    }
85	  | { success: false; error: string };
