179	// Printer(s) flagged prints_receipt get the priced customer receipt
180	// automatically at checkout — no manual "Cetak Struk" click needed. Kept
181	// separate from printJobs (kitchen tickets) so callers can dispatch the
182	// receipt first: same physical printer sometimes handles both roles, and
183	// Bluetooth sockets don't like concurrent jobs to the same device.
184	async function buildReceiptPrintJobsForTransaction(
185	  supabase: Awaited<ReturnType<typeof createClient>>,
186	  businessId: string,
187	  transactionId: string,
188	): Promise<KitchenPrintJobPayload[]> {
189	  // Query printer dan bangun buffer struk tidak saling bergantung — buffer
190	  // tidak butuh daftar printer sama sekali. Jalankan bersamaan, baru buang
191	  // hasil buffer kalau ternyata tidak ada printer prints_receipt.
192	  const [{ data: printers }, bufferResult] = await Promise.all([
193	    supabase
194	      .from("kitchen_printers")
195	      .select("name, connection_type, address")
196	      .eq("business_id", businessId)
197	      .eq("prints_receipt", true)
198	      .not("address", "is", null),
199	    buildReceiptBuffer(supabase, businessId, transactionId),
200	  ]);
201	
202	  if (!printers || printers.length === 0) return [];
203	  if (!bufferResult.success) return [];
204	
205	  const bytesBase64 = bufferResult.buffer.toString("base64");
206	  return printers.map((p) => ({
207	    printerName: p.name,
208	    address: p.address as string,
209	    connectionType: p.connection_type as "lan" | "bluetooth",
210	    bytesBase64,
211	  }));
212	}
