270	export type BuildTestPrintJobResult =
271	  | { success: true; job: KitchenPrintJobPayload }
272	  | { success: false; error: string };
273	
274	// One ticket, sent straight at a single chosen printer — no category
275	// routing, unlike buildKitchenPrintJobs (that one fans a real order out to
276	// every matching station). Used by the POS "Tes Cetak" screen.
277	export async function buildTestPrintJob(
278	  businessId: string,
279	  printerId: string,
280	): Promise<BuildTestPrintJobResult> {
281	  const supabase = await createClient();
282	  const { data: printer } = await supabase
283	    .from("kitchen_printers")
284	    .select("name, connection_type, address")
285	    .eq("id", printerId)
286	    .eq("business_id", businessId)
287	    .maybeSingle();
288	
289	  if (!printer) {
290	    return { success: false, error: "Printer tidak ditemukan." };
291	  }
292	  if (!printer.address) {
293	    return { success: false, error: "Printer ini belum diatur alamat/perangkatnya." };
294	  }
295	
296	  const buffer = buildKitchenTicket({
297	    station: printer.name,
298	    source: "Tes Cetak",
299	    label: new Date().toLocaleString("id-ID"),
300	    items: [{ name: "Ini tes cetak dari Kasirku", qty: 1 }],
301	  });
302	
303	  return {
304	    success: true,
305	    job: {
306	      printerName: printer.name,
307	      address: printer.address,
308	      connectionType: printer.connection_type as "lan" | "bluetooth",
309	      bytesBase64: buffer.toString("base64"),
310	    },
311	  };
312	}
