377	
378	  const summary = data as CloseShiftSummary;
379	  await logActivity(
380	    supabase,
381	    businessId,
382	    "sistem",
383	    summary.difference === 0 ? "info" : "warning",
384	    "Shift ditutup",
385	    `Penjualan Rp${summary.total_sales.toLocaleString("id-ID")} · ${summary.tx_count} transaksi · selisih Rp${summary.difference.toLocaleString("id-ID")}`,
