1	-- Module 8: checkout as a single atomic RPC. Everything (transaction row,
2	-- line items, payment row, stock decrement) happens in one Postgres
3	-- function call, so a failure partway through rolls back everything instead
4	-- of leaving an orphaned transaction. Price/cost/name/category are always
5	-- looked up from public.products server-side — never trusted from the
6	-- client — so a tampered request can't check out at a fake price.
7	
8	create or replace function public.checkout_transaction(
9	  p_business_id uuid,
10	  p_cashier_id uuid,
11	  p_items jsonb, -- array of {product_id, qty}
12	  p_payment_method text,
13	  p_received numeric default null
14	)
15	returns table (transaction_id uuid, invoice_number text)
16	language plpgsql
17	security definer
18	set search_path = ''
19	as $$
20	declare
21	  v_invoice_number text;
22	  v_seq int;
23	  v_subtotal numeric(12, 2) := 0;
24	  v_total_cost numeric(12, 2) := 0;
25	  v_transaction_id uuid;
26	  v_item jsonb;
27	  v_qty numeric(12, 2);
28	  v_product_id uuid;
29	  v_product record;
30	  v_change numeric(12, 2);
31	begin
32	  if not private.owns_business(p_business_id) then
33	    raise exception 'not authorized';
34	  end if;
35	
36	  if not exists (
37	    select 1 from public.cashiers c
38	    where c.id = p_cashier_id and c.business_id = p_business_id and c.active
39	  ) then
40	    raise exception 'invalid cashier';
41	  end if;
42	
43	  if p_payment_method is null or length(trim(p_payment_method)) = 0 then
44	    raise exception 'payment method required';
45	  end if;
46	
47	  if p_items is null or jsonb_array_length(p_items) = 0 then
48	    raise exception 'cart is empty';
49	  end if;
50	
51	  select count(*) + 1 into v_seq
52	  from public.transactions t
53	  where t.business_id = p_business_id
54	    and t.date::date = current_date;
55	
56	  v_invoice_number := 'INV-' || to_char(current_date, 'YYYYMMDD') || '-' || lpad(v_seq::text, 4, '0');
57	
58	  insert into public.transactions (
59	    business_id, cashier_id, invoice_number, date,
60	    subtotal_raw, subtotal, total, total_cost, gross_profit
61	  ) values (
62	    p_business_id, p_cashier_id, v_invoice_number, now(),
63	    0, 0, 0, 0, 0
64	  )
65	  returning id into v_transaction_id;
66	
67	  for v_item in select * from jsonb_array_elements(p_items)
68	  loop
69	    v_product_id := (v_item ->> 'product_id')::uuid;
70	    v_qty := (v_item ->> 'qty')::numeric;
71	
72	    if v_qty is null or v_qty <= 0 then
73	      raise exception 'invalid quantity';
74	    end if;
75	
76	    select * into v_product
77	    from public.products p
78	    where p.id = v_product_id
79	      and p.business_id = p_business_id
80	      and p.deleted_at is null;
81	
82	    if not found then
83	      raise exception 'product not found: %', v_product_id;
84	    end if;
85	
86	    insert into public.transaction_items (
87	      transaction_id, product_id, name, category, price, cost, qty
88	    ) values (
89	      v_transaction_id, v_product.id, v_product.name, v_product.category,
90	      v_product.price, v_product.cost, v_qty
91	    );
92	
93	    update public.products
94	    set stock = greatest(0, stock - v_qty)
95	    where id = v_product_id;
96	
97	    v_subtotal := v_subtotal + v_product.price * v_qty;
98	    v_total_cost := v_total_cost + v_product.cost * v_qty;
99	  end loop;
100	
101	  update public.transactions
102	  set subtotal_raw = v_subtotal,
103	      subtotal = v_subtotal,
104	      total = v_subtotal,
105	      total_cost = v_total_cost,
106	      gross_profit = v_subtotal - v_total_cost
107	  where id = v_transaction_id;
108	
109	  v_change := greatest(coalesce(p_received, v_subtotal) - v_subtotal, 0);
110	
111	  insert into public.transaction_payments (
112	    transaction_id, method, amount, received, change
113	  ) values (
114	    v_transaction_id, p_payment_method, v_subtotal, p_received, v_change
115	  );
116	
117	  return query select v_transaction_id, v_invoice_number;
118	end;
119	$$;
120	
121	grant execute on function public.checkout_transaction(uuid, uuid, jsonb, text, numeric) to authenticated;
122

1	-- Module 13: diskon (per item & per order), PPN, dan biaya layanan di
2	-- checkout. Kolom transactions (total_item_disc, order_disc_amt, service,
3	-- tax) dan businesses (tax_enabled/tax_rate/service_enabled/service_rate)
4	-- sudah ada sejak awal — migrasi ini mengisi mereka dengan angka sungguhan.
5	--
6	-- Urutan hitung (mengikuti aplikasi lama):
7	--   diskon item -> diskon order -> layanan dari subtotal -> PPN dari
8	--   (subtotal + layanan). Semua diskon divalidasi & di-clamp server-side.
9	
10	alter table public.transaction_items
11	  add column if not exists disc numeric(12, 2) not null default 0,
12	  add column if not exists disc_type text not null default 'pct'
13	    check (disc_type in ('pct', 'amt'));
14	
15	-- Signature lama harus di-drop dulu; kalau tidak, versi 5-argumen dan
16	-- 7-argumen hidup berdampingan dan pemanggilan lama jadi ambigu.
17	drop function if exists public.checkout_transaction(uuid, uuid, jsonb, text, numeric);
18	
19	create or replace function public.checkout_transaction(
20	  p_business_id uuid,
21	  p_cashier_id uuid,
22	  p_items jsonb, -- array of {product_id, qty, disc, disc_type}
23	  p_payment_method text,
24	  p_received numeric default null,
25	  p_order_disc numeric default 0,
26	  p_order_disc_type text default 'pct'
27	)
28	returns table (transaction_id uuid, invoice_number text)
29	language plpgsql
30	security definer
31	set search_path = ''
32	as $$
33	declare
34	  v_business record;
35	  v_invoice_number text;
36	  v_seq int;
37	  v_subtotal_raw numeric(12, 2) := 0;
38	  v_total_item_disc numeric(12, 2) := 0;
39	  v_order_disc_amt numeric(12, 2) := 0;
40	  v_subtotal numeric(12, 2);
41	  v_service numeric(12, 2) := 0;
42	  v_tax numeric(12, 2) := 0;
43	  v_total numeric(12, 2);
44	  v_total_cost numeric(12, 2) := 0;
45	  v_transaction_id uuid;
46	  v_item jsonb;
47	  v_qty numeric(12, 2);
48	  v_product_id uuid;
49	  v_product record;
50	  v_line_gross numeric(12, 2);
51	  v_disc numeric(12, 2);
52	  v_disc_type text;
53	  v_item_disc numeric(12, 2);
54	  v_change numeric(12, 2);
55	  v_shift_id uuid;
56	  v_recipe record;
57	begin
58	  if not private.owns_business(p_business_id) then
59	    raise exception 'not authorized';
60	  end if;
61	
62	  if not exists (
63	    select 1 from public.cashiers c
64	    where c.id = p_cashier_id and c.business_id = p_business_id and c.active
65	  ) then
66	    raise exception 'invalid cashier';
67	  end if;
68	
69	  if p_payment_method is null or length(trim(p_payment_method)) = 0 then
70	    raise exception 'payment method required';
71	  end if;
72	
73	  if p_items is null or jsonb_array_length(p_items) = 0 then
74	    raise exception 'cart is empty';
75	  end if;
76	
77	  if p_order_disc_type not in ('pct', 'amt') then
78	    raise exception 'invalid order discount type';
79	  end if;
80	
81	  if p_order_disc is null or p_order_disc < 0
82	     or (p_order_disc_type = 'pct' and p_order_disc > 100) then
83	    raise exception 'invalid order discount';
84	  end if;
85	
86	  select b.tax_enabled, b.tax_rate, b.service_enabled, b.service_rate
87	  into v_business
88	  from public.businesses b
89	  where b.id = p_business_id;
90	
91	  select id into v_shift_id
92	  from public.shifts
93	  where business_id = p_business_id and closed_at is null
94	  limit 1;
95	
96	  if v_shift_id is null then
97	    raise exception 'no active shift — open a shift before selling';
98	  end if;
99	
100	  select count(*) + 1 into v_seq
101	  from public.transactions t
102	  where t.business_id = p_business_id
103	    and t.date::date = current_date;
104	
105	  v_invoice_number := 'INV-' || to_char(current_date, 'YYYYMMDD') || '-' || lpad(v_seq::text, 4, '0');
106	
107	  insert into public.transactions (
108	    business_id, shift_id, cashier_id, invoice_number, date,
109	    subtotal_raw, subtotal, total, total_cost, gross_profit
110	  ) values (
111	    p_business_id, v_shift_id, p_cashier_id, v_invoice_number, now(),
112	    0, 0, 0, 0, 0
113	  )
114	  returning id into v_transaction_id;
115	
116	  for v_item in select * from jsonb_array_elements(p_items)
117	  loop
118	    v_product_id := (v_item ->> 'product_id')::uuid;
119	    v_qty := (v_item ->> 'qty')::numeric;
120	    v_disc := coalesce((v_item ->> 'disc')::numeric, 0);
121	    v_disc_type := coalesce(v_item ->> 'disc_type', 'pct');
122	
123	    if v_qty is null or v_qty <= 0 then
124	      raise exception 'invalid quantity';
125	    end if;
126	
127	    if v_disc_type not in ('pct', 'amt') then
128	      raise exception 'invalid item discount type';
129	    end if;
130	
131	    if v_disc < 0 or (v_disc_type = 'pct' and v_disc > 100) then
132	      raise exception 'invalid item discount';
133	    end if;
134	
135	    select * into v_product
136	    from public.products p
137	    where p.id = v_product_id
138	      and p.business_id = p_business_id
139	      and p.deleted_at is null;
140	
141	    if not found then
142	      raise exception 'product not found: %', v_product_id;
143	    end if;
144	
145	    v_line_gross := v_product.price * v_qty;
146	    v_item_disc := case v_disc_type
147	      when 'pct' then round(v_line_gross * v_disc / 100)
148	      else least(v_disc * v_qty, v_line_gross)
149	    end;
150	
151	    insert into public.transaction_items (
152	      transaction_id, product_id, name, category, price, cost, qty, disc, disc_type
153	    ) values (
154	      v_transaction_id, v_product.id, v_product.name, v_product.category,
155	      v_product.price, v_product.cost, v_qty, v_disc, v_disc_type
156	    );
157	
158	    update public.products
159	    set stock = greatest(0, stock - v_qty)
160	    where id = v_product_id;
161	
162	    -- Consume ingredients per the product's recipe (if any).
163	    for v_recipe in
164	      select pr.ingredient_id, pr.qty as recipe_qty
165	      from public.product_recipes pr
166	      where pr.product_id = v_product_id and pr.ingredient_id is not null
167	    loop
168	      insert into public.transaction_ingredient_consumption (
169	        transaction_id, ingredient_id, qty
170	      ) values (
171	        v_transaction_id, v_recipe.ingredient_id, v_recipe.recipe_qty * v_qty
172	      );
173	
174	      update public.ingredients
175	      set stock = greatest(0, stock - (v_recipe.recipe_qty * v_qty))
176	      where id = v_recipe.ingredient_id;
177	    end loop;
178	
179	    v_subtotal_raw := v_subtotal_raw + v_line_gross;
180	    v_total_item_disc := v_total_item_disc + v_item_disc;
181	    v_total_cost := v_total_cost + v_product.cost * v_qty;
182	  end loop;
183	
184	  v_order_disc_amt := case p_order_disc_type
185	    when 'pct' then round((v_subtotal_raw - v_total_item_disc) * p_order_disc / 100)
186	    else least(p_order_disc, v_subtotal_raw - v_total_item_disc)
187	  end;
188	
189	  v_subtotal := v_subtotal_raw - v_total_item_disc - v_order_disc_amt;
190	
191	  if v_business.service_enabled then
192	    v_service := round(v_subtotal * v_business.service_rate / 100);
193	  end if;
194	
195	  if v_business.tax_enabled then
196	    v_tax := round((v_subtotal + v_service) * v_business.tax_rate / 100);
197	  end if;
198	
199	  v_total := v_subtotal + v_service + v_tax;
200	
201	  update public.transactions
202	  set subtotal_raw = v_subtotal_raw,
203	      subtotal = v_subtotal,
204	      total_item_disc = v_total_item_disc,
205	      order_disc_amt = v_order_disc_amt,
206	      service = v_service,
207	      tax = v_tax,
208	      total = v_total,
209	      total_cost = v_total_cost,
210	      gross_profit = v_subtotal - v_total_cost
211	  where id = v_transaction_id;
212	
213	  v_change := greatest(coalesce(p_received, v_total) - v_total, 0);
214	
215	  insert into public.transaction_payments (
216	    transaction_id, method, amount, received, change
217	  ) values (
218	    v_transaction_id, p_payment_method, v_total, p_received, v_change
219	  );
220	
221	  return query select v_transaction_id, v_invoice_number;
222	end;
223	$$;
